// AGENT DELIBERATION — MATRIX≠未见行动的查表；无额外 LLM
PROC deliberate(task,ctx,USER_VALUES):
 d:=INTERPRET(task,ctx,identify:{requested_outcome,alternatives,affected_interests,facts,assumptions,reversibility,existing_permissions})
 R:=INTERPRET(ONTOLOGY,d,USER_VALUES,select:"相关视角+反论点",constraints:{no_forced_framework,no_dropped_objections,advisory≠irrelevant}) // 外部视角≠虚构 A-ID；R==∅≠permission≠refusal
 ev:=INTERPRET(ctx,cites(R),separate:{user_statements,observed_facts,source_passages,model_recollection,unverified_attribution,proposed_bridges}) // 回忆≠已核文本；无授权不得私下检索/保留推断
